
import Link from "next/link";

import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

import { getImageUrl, type Product } from "@/lib/strapi";
import { formatPrice } from "@/lib/utils";

export function ProductCard({ product }: { product: Product }) {
  return (
    <Card className="overflow-hidden">
      {product.image && (
        <img
          src={getImageUrl(
            product.image.formats?.small?.url ?? product.image.url
          )}
          alt={product.image.alternativeText ?? product.name}
          width={400}
          height={300}
          className="h-48 w-full object-cover"
        />
      )}

      <CardHeader>
        <CardTitle>{product.name}</CardTitle>
      </CardHeader>

      <CardContent className="space-y-2">
        <p className="text-lg font-semibold">
          {formatPrice(Number(product.price))}
        </p>

        {product.stock === 0 && (
          <Badge variant="destructive">Agotado</Badge>
        )}

        {product.stock > 0 && (
          <p className="text-sm text-muted-foreground">
            Disponibles: {product.stock}
          </p>
        )}
      </CardContent>

      <CardFooter>
        <Link
          href={`/productos/${product.slug}`}
          className="inline-flex w-full items-center justify-center rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground hover:opacity-90"
        >
          Ver detalle
        </Link>
      </CardFooter>
    </Card>
  );
}
